#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor resize_with_antialias_custom_impl_npu(const at::Tensor& x) {
    // 输出尺寸固定为(128,128)，与模型一致
    std::vector<int64_t> out_sizes = x.sizes().vec();
    out_sizes[2] = 128;
    out_sizes[3] = 128;
    at::Tensor y = at::empty(out_sizes, x.options());
    EXEC_NPU_CMD(aclnnResizeWithAntialiasCustom, x, y);
    return y;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("resize_with_antialias_custom", &resize_with_antialias_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("resize_with_antialias_custom", &resize_with_antialias_custom_impl_npu, "Resize with antialias custom op");
}
